          "name": "Сопротивление (Жар)",
          "description": "<p>Персонаж приобретает устойчивость к определённому виду опасности благодаря опыту, тренировке или природным особенностям. При проверках сопротивления выбранному типу воздействия он получает бонус +10. Выбор специализации может требовать согласования с мастером.</p><p>Стр. 131.</p>",
          "sourceDescription": "<p>The Acolyte’s background, experience, training, exposure, or plain stubbornness has developed a resistance within him. Each time he selects this talent, choose one area of resistance. He gains a +10 bonus when making tests to resist effects of this type. The GM can require approval for certain choices, or justification based on the Acolyte’s past.</p><p>p. 131</p>",
