    "Temple Revelationist": {
      "name": "Храмовый откровенник",
      "sourceId": "3lZ1ZZLyQcI4jiCv",
      "items": {
        "Strike": {
          "name": "Удар",
          "description": "",
          "sourceDescription": "",
          "sourceItemId": "Dmz6oQlXX7GQnAaw"
        },
        "Peer (Ecclesiarchy)": {
          "name": "Связи (Экклезиархия)",
          "description": "<p>Персонаж знаком со структурами и обычаями выбранной группы и пользуется её расположением. Он получает +10 к проверкам Общительности и Влияния при общении с её представителями. По решению мастера может обращаться к ним за услугами. Повторное приобретение увеличивает бонус по +10 за каждую ступень таланта; при первом приобретении Влияние повышается на 1.</p><p>Стр. 130.</p>",
          "sourceDescription": "<p>The Acolyte knows how to deal with a particular social group or organisation, or even xenos race. He gains a +10 bonus to all Fellowship and Influence tests when interacting with this chosen group, and at the GM’s discretion can sometimes call upon them for favours. The GM and player may agree to award this talent when appropriate to the adventure or campaign, though the character must still pay the experience cost for the Talent as normal. This talent can be awarded multiple times for the same group, in which case it should be listed as Peer (X), with X equalling the number of times the talent has been awarded. This can be used to represent groups who particularly like the character and may even be staunch allies. In game terms, the bonus to Fellowship tests increases to +10 times X. Additionally, when the character acquires this talent, he increases his Influence by 1.</p><p>p. 130</p>",
          "sourceItemId": "ISDKWA8nmKRdz1X9"
        },
        "Hatred (Heretics)": {
          "name": "Ненависть (Еретики)",
          "description": "<p>Персонаж питает сильную ненависть к выбранной группе. В ближнем бою против её представителей он получает +10 к проверкам Навыка рукопашного боя. Отступить или сдаться при столкновении с ненавистным врагом можно после успешной Обычной (+0) проверки Силы воли, если только превосходство врага не делает сопротивление самоубийством.</p><p>Стр. 128.</p>",
          "sourceDescription": "<p>A group, organisation, or race has wronged the character in the past, fuelling this animosity. When fighting opponents of that group in close combat, the Acolyte gains a +10 bonus to all Weapon Skill tests made against them. He also finds it difficult to back down from a fight with his hated foe, and must make a Challenging (+0) Willpower test to retreat or surrender when fighting them, unless suicidally outnumbered or outclassed.</p><p>p. 128</p>",
          "sourceItemId": "pRzjP5k51P9IUFbo"
        },
        "Flamer": {
          "name": "Огнемет",
          "description": "",
          "sourceDescription": "",
          "sourceItemId": "GAigr9CKOMddBAdh"
        },
        "Partial flak armour": {
          "name": "Неполная флак-броня",
          "description": "<p>Очки брони — Корпус: 3, Правая рука: 3, Левая рука: 3, Правая нога: 3, Левая нога: 3.</p><p>Стр. 390.</p>",
          "sourceDescription": "<p>body 3, rightArm 3, leftArm 3, rightLeg 3, leftLeg 3 AP (p. 390)</p>",
          "sourceItemId": "b4c6GUEqI5IRofiX"
        },
        "Respirator/Gas Mask": {
          "name": "Респиратор",
          "description": "<p>Простая дыхательная маска, покрывающая нос и рот или все лицо, обеспечивая гораздо лучшую защиту, чем фильтры-затычки . Персонаж, надевающий респиратор, получает +30 бонус к проверке Выносливости на сопротивление воздействию газа, и может перекинуть проваленный результат. Модели хорошего качества добавляют дополнительно +10, в то время как модели Низкого качества должны быть заменены через 10 часов использования, так как фильтр забивается и непригоден для использования.</p><p>стр. 209</p>",
          "sourceDescription": "<p>A simple breathing mask that covers the nose and mouth or entire face, these offer much better protection than filtration plugs. A character wearing a respirator gains a +30 bonus to a Toughness test made to resist the effects of gas and can re-roll the test if failed. Good craftsmanship models add another +10 bonus, while Poor models must be replaced after 10 hours of usage as the filter becomes clogged and unusable.</p><p>p. </p>",
          "sourceItemId": "QcMFhiXo0Zv9sSQq"
        },
        "Sacred incense": {
          "name": "Священные благовония",
          "description": "<p>Снаряжение персонажа «Храмовый откровенник».</p><p>Стр. 390.</p>",
          "sourceDescription": "<p>Temple Revelationist (p. 390)</p>",
          "sourceItemId": "xFLXcp9W1tnnjkGo"
        },
        "Several large holy books": {
          "name": "Несколько больших священных книг",
          "description": "<p>Снаряжение персонажа «Храмовый откровенник».</p><p>Стр. 390.</p>",
          "sourceDescription": "<p>Temple Revelationist (p. 390)</p>",
          "sourceItemId": "yTD4qLYEB0C7QDaN"
        },
        "Battered oath-cog": {
          "name": "Потрёпанный клятвенный механизм",
          "description": "<p>Снаряжение персонажа «Храмовый откровенник».</p><p>Стр. 390.</p>",
          "sourceDescription": "<p>Temple Revelationist (p. 390)</p>",
          "sourceItemId": "Y2DOAbNcOuoiYhQh"
        },
        "Flamer Fuel Canister": {
          "name": "Топливная канистра огнемета",
          "description": "<p>Полный магазин стандартных боеприпасов для оружия «Огнемет»: 6 выстрелов. Доступность стандартных боеприпасов на одну ступень выше, чем соответствующего оружия; полный магазин весит 10% массы оружия.</p><p>Стр. 166.</p>",
          "sourceDescription": "<p>A full clip of standard ammunition for the Flamer: 6 shots. Standard ammunition is one Availability level more available than its weapon, and a full clip weighs 10% of the weapon.</p><p>p. 166</p>",
          "sourceItemId": "3YyR0MDXDIZBPaas"
        }
      }
    },
