    "Desoleum Bondless Dealer": {
      "name": "Десолеумский бесклятвенный делец",
      "sourceId": "vmHvw7Qm9a4c3waX",
      "items": {
        "Strike": {
          "name": "Удар",
          "description": "",
          "sourceDescription": "",
          "sourceItemId": "TCBn4gvaYuTQJL60"
        },
        "Face in a Crowd": {
          "name": "Лицо В Толпе",
          "description": "<p>Ранг: 2 Требования: Разговор с Толпой, Общительность 35 Склонности: Общительность, Общение Успешное расследование часто включает в себя слежку за подозреваемым, в ходе которой аколит передвигается по незнакомому ему району – он не знает, где найти укрытие, как спрятаться от глаз еретиков или преступников. С опытом аколит научится избегать чужого внимания, искусно смешиваясь с толпой или даже незаметно присоединяясь к нужной ему группе людей. Персонаж, использующий Слежку (особое применение Скрытности) может использовать для проверок свою Общительность вместо Ловкости.</p>",
          "sourceDescription": "<p>A successful investigation often involves trailing suspects without their knowledge, the better to follow them to hidden dens of heretical worship or criminal activity. With training, the Acolyte can ensure none notice his presence, through careful replication of a crowd’s mannerisms or even joining gatherings while still keeping a careful eye on his quarry. When employing the Shadowing special use of the Stealth skill, he can use his Fellowship characteristic instead of his Agility.</p><p>p. 127</p>",
          "sourceItemId": "GMSNb47NuzRmFPbd"
        },
        "Jaded": {
          "name": "Искушённый",
          "description": "<p>Ранг: 1 Требования: Сила Воли 40 Склонности: Сила Воли, Защита В своих путешествиях аколит повидал куда больше, как чудес, так и ужасов, чем многие другие. Галактика столкнула его с худшим, но он не дрогнул. «Обыденные» ужасы, вроде созерцания жуткой сцены убийства или встречи с мерзкими ксеносами не оказывают влияния на персонажа, не могут принести ему очки Безумия или заставить сделать проверку Страха. Однако, встречи с демонами, проявления Варпа и другие сверхъестественные ужасы действуют на аколита по-прежнему.</p>",
          "sourceDescription": "<p>The Acolyte’s wide travels have shown him both wonders and horrors beyond the ken of most. The galaxy has thrown its worst at him and he has yet to flinch. Mundane events, from death’s horrific visage to xenos abominations, do not force him to gain Insanity points or make Fear tests. Daemons, Warp manifestations, and other unnatural effects still affect him normally.</p><p>p. 128</p>",
          "sourceItemId": "5rvE0V6mhyaJ0EQt"
        },
        "Laspistol": {
          "name": "Лазпистолет",
          "description": "",
          "sourceDescription": "",
          "sourceItemId": "9CAMLrZ0FCyMHurM"
        },
        "Light flak armour under subtle clothing": {
          "name": "Лёгкая флак-броня под неприметной одеждой",
          "description": "<p>Очки брони — Корпус: 2, Правая рука: 2, Левая рука: 2, Правая нога: 2, Левая нога: 2.</p><p>Стр. 386.</p>",
          "sourceDescription": "<p>body 2, rightArm 2, leftArm 2, rightLeg 2, leftLeg 2 AP (p. 386)</p>",
          "sourceItemId": "iyQGAmRDLQcFuIdS"
        },
        "Clothing": {
          "name": "Одежда",
          "description": "<p>Стили одежды сильно различаются по всему Империуму, некоторые предоставляют базовую защиту, не думая об эстетике, некоторые сосредотачиваются на украшении, не беспокоясь об окружающей среде или о иных меньших заботах. Для некоторых стили одежды устанавливаются при рождении или по заводским диктатам. Другие принимают стили своей банды, секты, дома или иной принадлежности. В то время как базовая одежда, обычная для местности, должна быть простой в приобретении, более сложный, высокостатусный или предназначенный для особой цели наряд должно быть сложнее найти, а мастер игры выступает в качестве окончательного арбитра по его доступности или созданию. енал</p><p>стр. 208</p>",
          "sourceDescription": "<p>Clothing styles vary greatly across the Imperium, some as basic protection with no thought to aesthetics, some purely ornamental with no concern for environmental or other lesser worries. For some, clothing styles are set at birth or through factory dictates. Others adopt the styles of their gang, sect, house, or other affiliation. While basic clothing common to a setting should be simple to acquire, more elaborate garb of either higher status or specialised function should be more difficult, with the GM acting as final arbiter on Availability or creation.</p><p>p. </p>",
          "sourceItemId": "ia3IROerW77iBG3l"
        },
        "Assorted legal and somewhat illegal merchandise": {
          "name": "Разнообразные законные и полулегальные товары",
          "description": "<p>Снаряжение персонажа «Десолеумский бесклятвенный делец».</p><p>Стр. 386.</p>",
          "sourceDescription": "<p>Desoleum Bondless Dealer (p. 386)</p>",
          "sourceItemId": "yRtSfaUSM2OmH4Yl"
        },
        "Several false oath-cogs": {
          "name": "Несколько поддельных клятвенных механизмов",
          "description": "<p>Снаряжение персонажа «Десолеумский бесклятвенный делец».</p><p>Стр. 386.</p>",
          "sourceDescription": "<p>Desoleum Bondless Dealer (p. 386)</p>",
          "sourceItemId": "FVpEgSksvGTdIh1G"
        },
        "Laspistol Charge Pack": {
          "name": "Энергобатарея лазпистолета",
          "description": "<p>Полный магазин стандартных боеприпасов для оружия «Лазпистолет»: 30 выстрелов. Доступность стандартных боеприпасов на одну ступень выше, чем соответствующего оружия; полный магазин весит 10% массы оружия.</p><p>Стр. 166.</p>",
          "sourceDescription": "<p>A full clip of standard ammunition for the Laspistol: 30 shots. Standard ammunition is one Availability level more available than its weapon, and a full clip weighs 10% of the weapon.</p><p>p. 166</p>",
          "sourceItemId": "Rrm3a6ELlPChmrzr"
        }
      }
    },
